sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    try {
        var userId = request.pathParams.user_id;
        gs.info('【API请求】用户ID：' + userId);


        // 1. 校验参数是否存在
        if (!userId) {
            gs.error('【400错误】用户ID为空');
            response.setStatus(400); // 明确返回400状态码
            response.setBody({error: '参数错误：user_id不能为空'});
            return;
        }

        // 2. 校验sys_id格式（32位字母数字）
        var sysIdRegex = /^[0-9a-f]{32}$/i;
        if (!sysIdRegex.test(userId)) {
            gs.error('【400错误】用户ID格式非法：' + userId);
            response.setStatus(400);
            response.setBody({error: '参数错误：user_id不是合法的sys_id'});
            return;
        }

        // 3. 正常查询逻辑
        var userGR = new GlideRecord('sys_user');
        if (userGR.get(userId)) {
            response.setBody({email: userGR.email.toString() || ''});
        } else {
            response.setBody({email: ''});
        }
    } catch (e) {
        gs.error('【API异常】' + e.message);
        response.setStatus(500);
        response.setBody({error: '服务器内部错误'});
    }
})(request, response);
